public struct XrSpaceUserFB_T : IEquatable<XrSpaceUserFB_T>
{
    // Native OpenXR handles are 64-bit integers or pointers depending on the platform spec.
    private readonly ulong handle;

    public XrSpaceUserFB_T(ulong handle) => this.handle = handle;

