[StructLayout(LayoutKind.Sequential)]
public readonly struct XrSoundObstacleMaterialBD_T : IEquatable<XrSoundObstacleMaterialBD_T>
{
    // OpenXR non-dispatchable handles are structurally 64-bit integers
    private readonly ulong _handle;

    public XrSoundObstacleMaterialBD_T(ulong handle)
    {
        _handle = handle;
    }

    public ulong Value => _handle;

    public bool IsNull => _handle == 0;

    public static XrSoundObstacleMaterialBD_T Null => new XrSoundObstacleMaterialBD_T(0);

    public bool Equals(XrSoundObstacleMaterialBD_T other) => _handle == other._handle;

    public override bool Equals(object? obj) => obj is XrSoundObstacleMaterialBD_T other && Equals(other);

    public override int GetHashCode() => _handle.GetHashCode();

    public override string ToString() => $"0x{_handle:X}";

    public static bool operator ==(XrSoundObstacleMaterialBD_T left, XrSoundObstacleMaterialBD_T right) => left.Equals(right);

    public static bool operator !=(XrSoundObstacleMaterialBD_T left, XrSoundObstacleMaterialBD_T right) => !left.Equals(right);
}

